-- Step AI-R: AI assistant reports
-- (docs/plan/steps/31-ai-chat-reports.md §3, D2, D5-D8; ADR-0095, ADR-0094 amendment AI-R).
--
-- Additive only (two new tables, none partitioned: 176 -> 178 tables, 41 partitioned; nothing
-- existing is altered, no data section, no permission):
--   * ai_chat_reports: one row per report generated by the native tool `report_generate`. The
--     HTML itself is stored in object storage (mail bucket, `object_key`
--     `org/<organizationId>/assistant/report/<yyyy>/<mm>/<dd>/<publicId>.html`); the row holds
--     metadata only (window, sections, figures, size, SHA-256, statuses). The row is written
--     `pending` before the PutObject and becomes `available` in the execution's persist
--     transaction; content purge sets `purged`, the retention job deletes the object afterwards
--     (`object_deleted_at`, `object_key` NULL).
--   * ai_chat_report_deliveries: one row per confirmed report email, written with the outbox
--     event `assistant.report.email_requested.v1` in the confirm transaction; one per
--     confirmation (UQ confirmation_id). `recipient_address` is content (purged with the
--     conversation); `recipient_sha256` stays for the audit trail.
--   * Foreign keys: organizations RESTRICT (the organization purge deletes deliveries, then
--     reports and their objects, before the conversations; AssistantTenantDataRepository);
--     ai_chat_reports.conversation_id -> ai_chat_conversations CASCADE (backstop; the purge order
--     is explicit); ai_chat_report_deliveries.report_id -> ai_chat_reports CASCADE. No FK on
--     `user_id` (users are soft-deleted; the trail survives), `execution_id`, `confirmation_id`
--     or ai_chat_report_deliveries.conversation_id (the report cascades).
--   * Indexes (organization_id first in secondary indexes that carry it):
--     ai_chat_reports: UQ public_id, UQ execution_id (one report per execution),
--       (organization_id, user_id, created_at) (daily generation limit; backs the organization
--       FK), (conversation_id, status, created_at) (latest available report of a conversation,
--       content purge; backs the conversation FK), (status, object_deleted_at, id) (object purge
--       batches), (status, created_at) (pending sweep).
--     ai_chat_report_deliveries: UQ public_id (the event id), UQ confirmation_id,
--       (organization_id, requested_at) (tenant daily limit; backs the organization FK),
--       (organization_id, user_id, requested_at) (user daily limit), (report_id, requested_at)
--       (deliveries of a report, newest first; backs the report FK), (status, requested_at)
--       (queued-delivery timeout sweep).
--
-- Locking: both tables are created empty; adding their foreign keys takes a short metadata lock
-- on organizations and ai_chat_conversations (and on the new ai_chat_reports).
--
-- Rollback (never automatic; after rolling the api, the notification-worker and the portal
-- back, AI-R being the only reader and writer of both tables; delete the report objects under
-- `org/*/assistant/report/` of the mail bucket first if they should not outlive the rows):
--   DROP TABLE ai_chat_report_deliveries;
--   DROP TABLE ai_chat_reports;
--   Then delete the migration's `_prisma_migrations` row. See docs/database/README.md.

-- 1. ai_chat_reports (§3, D2, D6, D7).
CREATE TABLE `ai_chat_reports` (
    `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `public_id` CHAR(36) NOT NULL,
    `organization_id` BIGINT UNSIGNED NOT NULL,
    `user_id` BIGINT UNSIGNED NOT NULL,
    `platform_override_id` CHAR(36) NULL,
    `conversation_id` BIGINT UNSIGNED NOT NULL,
    `execution_id` BIGINT UNSIGNED NULL,
    `status` ENUM('pending', 'available', 'failed', 'purged') NOT NULL DEFAULT 'pending',
    `title` VARCHAR(200) NOT NULL,
    `period_from` DATETIME(3) NOT NULL,
    `period_to` DATETIME(3) NOT NULL,
    `granularity` ENUM('hour', 'day') NOT NULL,
    `sections` JSON NOT NULL,
    `figures` JSON NOT NULL,
    `template_version` VARCHAR(32) NOT NULL,
    `object_key` VARCHAR(512) NULL,
    `size_bytes` INTEGER UNSIGNED NULL,
    `sha256` CHAR(64) NULL,
    `error_code` VARCHAR(64) NULL,
    `purged_at` DATETIME(3) NULL,
    `object_deleted_at` DATETIME(3) NULL,
    `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `updated_at` DATETIME(3) NOT NULL,

    UNIQUE INDEX `ai_chat_reports_public_id_key`(`public_id`),
    UNIQUE INDEX `ai_chat_reports_execution_id_key`(`execution_id`),
    INDEX `ai_chat_reports_organization_id_user_id_created_at_idx`(`organization_id`, `user_id`, `created_at`),
    INDEX `ai_chat_reports_conversation_id_status_created_at_idx`(`conversation_id`, `status`, `created_at`),
    INDEX `ai_chat_reports_status_object_deleted_at_id_idx`(`status`, `object_deleted_at`, `id`),
    INDEX `ai_chat_reports_status_created_at_idx`(`status`, `created_at`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- 2. ai_chat_report_deliveries (§3, D5, D8).
CREATE TABLE `ai_chat_report_deliveries` (
    `id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
    `public_id` CHAR(36) NOT NULL,
    `organization_id` BIGINT UNSIGNED NOT NULL,
    `user_id` BIGINT UNSIGNED NOT NULL,
    `conversation_id` BIGINT UNSIGNED NOT NULL,
    `report_id` BIGINT UNSIGNED NOT NULL,
    `confirmation_id` BIGINT UNSIGNED NOT NULL,
    `recipient_address` VARCHAR(320) NULL,
    `recipient_sha256` CHAR(64) NOT NULL,
    `recipient_kind` ENUM('self', 'member', 'domain') NOT NULL,
    `status` ENUM('queued', 'sent', 'failed') NOT NULL DEFAULT 'queued',
    `error_code` VARCHAR(64) NULL,
    `message_id` VARCHAR(255) NULL,
    `size_bytes` INTEGER UNSIGNED NOT NULL,
    `correlation_id` VARCHAR(128) NOT NULL,
    `requested_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
    `sent_at` DATETIME(3) NULL,
    `updated_at` DATETIME(3) NOT NULL,

    UNIQUE INDEX `ai_chat_report_deliveries_public_id_key`(`public_id`),
    UNIQUE INDEX `ai_chat_report_deliveries_confirmation_id_key`(`confirmation_id`),
    INDEX `ai_chat_report_deliveries_organization_id_requested_at_idx`(`organization_id`, `requested_at`),
    INDEX `ai_chat_report_deliveries_organization_id_user_id_requested__idx`(`organization_id`, `user_id`, `requested_at`),
    INDEX `ai_chat_report_deliveries_report_id_requested_at_idx`(`report_id`, `requested_at`),
    INDEX `ai_chat_report_deliveries_status_requested_at_idx`(`status`, `requested_at`),
    PRIMARY KEY (`id`)
) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;

-- 3. Foreign keys (empty tables).
ALTER TABLE `ai_chat_reports` ADD CONSTRAINT `ai_chat_reports_organization_id_fkey` FOREIGN KEY (`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE `ai_chat_reports` ADD CONSTRAINT `ai_chat_reports_conversation_id_fkey` FOREIGN KEY (`conversation_id`) REFERENCES `ai_chat_conversations`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE `ai_chat_report_deliveries` ADD CONSTRAINT `ai_chat_report_deliveries_organization_id_fkey` FOREIGN KEY (`organization_id`) REFERENCES `organizations`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE;

ALTER TABLE `ai_chat_report_deliveries` ADD CONSTRAINT `ai_chat_report_deliveries_report_id_fkey` FOREIGN KEY (`report_id`) REFERENCES `ai_chat_reports`(`id`) ON DELETE CASCADE ON UPDATE CASCADE;
